ALTER TABLE task_run_parameters ADD COLUMN IF NOT EXISTS request_id integer;
CREATE INDEX IF NOT EXISTS ix_task_parameters_rest_step ON task_parameters ((rest_source ->> 'step_id')) WHERE source_type='rest';
CREATE INDEX IF NOT EXISTS ix_task_run_parameters_request ON task_run_parameters(request_id);
DROP INDEX IF EXISTS ix_task_parameters_rest_interface;
